class Solution {
    public int maxScore(String text){
        int rightOnes=0;
        for(char value:text.toCharArray())if(value=='1')rightOnes++;
        int leftZeros=0,answer=0;
        for(int i=0;i<text.length()-1;i++){
            if(text.charAt(i)=='0')leftZeros++;
            else rightOnes--;
            answer=Math.max(answer,leftZeros+rightOnes);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maxScore(text:String):Int{
        var rightOnes=text.count{
            it=='1'
        };
        var leftZeros=0;
        var answer=0;
        for(i in 0 until text.lastIndex){
            if(text[i]=='0')leftZeros++ else rightOnes--;
            answer=maxOf(answer,leftZeros+rightOnes)
        };
        return answer
    }
}

